  values ('mrkvove-pyre', 'Mrkvové pyré', 'Sladká a jemná klasika, se kterou začíná většina miminek.', 6, 12, 20, '2–3 malé porce', array['Mrkev oloupejte a nakrájejte na kolečka.', 'Vařte ji v malém množství vody doměkka, asi 15 minut.', 'Rozmixujte dohladka. Podle potřeby zřeďte vodou z vaření.']::text[], 'Nový druh zeleniny zkoušejte vždy po jednom a pár dní pozorujte, jak ho miminko snáší.', 'pyre', 'Jak na mateřství', 'https://jaknamaterstvi.cz/recepty-od-6-mesicu/', true)
