  values ('jahlova-kase-s-jablky', 'Jáhlová kaše s jablky', 'Teplá bezlepková snídaně, která zasytí.', 8, null, 30, '4 porce', array['Jáhly několikrát propláchněte teplou vodou, zbaví se tak hořkosti.', 'Zalijte je mlékem a přidejte nastrouhaná jablka.', 'Vařte na mírném plameni a míchejte, dokud se tekutina nevsákne.']::text[], 'Kaše jde uvařit i na vodě, pak je bez mléka.', 'kase', 'Máma v kuchyni', 'https://mamavkuchyni.cz/jahlova-kase/', true)
